import 'package:flutter/widgets.dart';

/// The white W of the Wince mark in three layers, all on the same square canvas, so
/// stacking them gives the whole mark. Generated by tool/art/wince/make_w_icons.py.
const kMarkLeft = 'assets/brand/w_left.webp';
const kMarkMiddle = 'assets/brand/w_middle.webp';
const kMarkRight = 'assets/brand/w_right.webp';
const kMarkLayers = [kMarkLeft, kMarkMiddle, kMarkRight];

/// The W, built up for the splash. [middle] (0–1) brings the centre stroke in, [legs]
/// (0–1) slides the two cut legs down their slant into place, [flinch] (0–1, peaking
/// mid-way) is the wince: a quick squeeze as the legs land. [sheen] sweeps a highlight
/// across the face (off outside 0–1). The defaults show the finished mark.
class BrandMark extends StatelessWidget {
  const BrandMark({super.key, required this.size, this.middle = 1, this.legs = 1, this.flinch = 0, this.sheen = -1});
  final double size, middle, legs, flinch, sheen;

  // Each leg travels along its own slant, up and outward, as a fraction of [size].
  static const _legTravel = Offset(0.11, -0.30);

  Widget _layer(String asset) => Image.asset(asset, width: size, height: size, filterQuality: FilterQuality.medium);

  Widget _leg(String asset, double dir) {
    final away = 1 - legs.clamp(0.0, 1.0);
    return Opacity(
      opacity: Curves.easeOut.transform(legs.clamp(0.0, 1.0)),
      child: Transform.translate(
        offset: Offset(_legTravel.dx * dir, _legTravel.dy) * size * away,
        child: _layer(asset),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final m = middle.clamp(0.0, 1.0);
    final squeeze = 1 - 0.05 * Curves.easeOut.transform(flinch.clamp(0.0, 1.0));
    final mark = Stack(
      children: [
        Opacity(
          opacity: m,
          child: Transform.translate(offset: Offset(0, (1 - m) * size * 0.06), child: _layer(kMarkMiddle)),
        ),
        _leg(kMarkLeft, -1),
        _leg(kMarkRight, 1),
      ],
    );
    return SizedBox.square(
      dimension: size,
      child: Transform(
        alignment: Alignment.bottomCenter,
        transform: Matrix4.diagonal3Values(squeeze, 2 - squeeze, 1),
        child: Stack(
          children: [
            mark,
            if (sheen > 0 && sheen < 1)
              ShaderMask(
                blendMode: BlendMode.srcATop,
                shaderCallback: (r) {
                  final c = -0.4 + 1.8 * sheen; // band centre travels across, top-left to bottom-right
                  return LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: const [Color(0x00FFFFFF), Color(0x88FFFFFF), Color(0x00FFFFFF)],
                    stops: [(c - 0.12).clamp(0.0, 1.0), c.clamp(0.0, 1.0), (c + 0.12).clamp(0.0, 1.0)],
                  ).createShader(r);
                },
                child: mark,
              ),
          ],
        ),
      ),
    );
  }
}
